/**
 * Génère un SVG inline pour une icône Lucide
 *
 * @param string $name Nom de l'icône
 * @param int $size Taille en pixels
 * @param string $class Classes CSS additionnelles
 * @param string $stroke Couleur du trait
 * @param float $weight Épaisseur du trait
 */
function icon(string $name, int $size = 24, string $class = '', string $stroke = 'currentColor', float $weight = 2): string
{
    if (!isset(ICONS[$name])) {
        return '<!-- icône inconnue : ' . htmlspecialchars($name) . ' -->';
    }

    $classAttr = $class ? ' class="icon ' . htmlspecialchars($class) . '"' : ' class="icon"';

    return '<svg'
        . $classAttr
        . ' width="' . $size . '"'
        . ' height="' . $size . '"'
        . ' viewBox="0 0 24 24"'
        . ' fill="none"'
        . ' stroke="' . htmlspecialchars($stroke) . '"'
        . ' stroke-width="' . $weight . '"'
        . ' stroke-linecap="round"'
        . ' stroke-linejoin="round"'
        . ' aria-hidden="true">'
        . ICONS[$name]
        . '</svg>';
}
